function previewSections(){prepareSections();return working.sections.flatMap(section=>section.pages.map(body=>`<section class="preview-layout-section" style="${pageStyle(section.pageSetup)}"><div class="preview-layout-header">${section.header}</div><div class="preview-layout-body">${body}</div><div class="preview-layout-footer">${section.footer}</div></section>`)).join('')}
function showPageSetup(sectionIndex,onApply){
  const target=Math.min(Math.max(sectionIndex,0),working.sections.length-1);
  $('#modal-root').innerHTML=`<div class="overlay"><div class="modal setup-modal" role="dialog" aria-modal="true" aria-labelledby="setup-title"><div class="modal-head"><h2 id="setup-title">Page setup</h2><button class="icon-button" id="modal-close" aria-label="Close">×</button></div><div class="modal-body"><div class="setup-pages-tab">Pages</div><div class="field setup-field"><label for="setup-scope">Apply to</label><select id="setup-scope"><option value="all">Whole document</option>${working.sections.map((s,i)=>`<option value="${i}" ${i===target?'selected':''}>This section (Section ${i+1})</option>`).join('')}</select></div><div class="setup-field"><label>Orientation</label><div class="orientation-choices"><label><input type="radio" name="orientation" value="Portrait"> Portrait</label><label><input type="radio" name="orientation" value="Landscape"> Landscape</label></div></div><div class="setup-size-row"><div class="field"><label for="setup-size">Paper size</label><select id="setup-size">${Object.keys(PAGE_SIZES).map(size=>`<option>${size}</option>`).join('')}</select></div><div class="field"><label for="setup-color">Page color</label><input id="setup-color" type="color" aria-label="Page color"></div></div><div class="setup-field"><label>Margins (inches)</label><div class="setup-margins">${['top','bottom','left','right'].map(side=>`<div class="field"><label for="margin-${side}">${side[0].toUpperCase()+side.slice(1)}</label><input class="input" id="margin-${side}" type="number" min="0" max="5" step="0.1"></div>`).join('')}</div></div><p id="setup-error" class="error" role="alert"></p></div><div class="modal-actions"><button class="button" id="modal-cancel">Cancel</button><button class="button primary" id="setup-apply">Apply</button></div></div></div>`;
  function loadSettings(){const value=$('#setup-scope').value,settings=working.sections[value==='all'?target:+value].pageSetup;document.querySelector(`[name="orientation"][value="${settings.orientation}"]`).checked=true;$('#setup-size').value=settings.size;$('#setup-color').value=settings.color;['top','bottom','left','right'].forEach(side=>$('#margin-'+side).value=settings[side])}loadSettings();$('#setup-scope').onchange=loadSettings;$('#modal-close').onclick=closeModal;$('#modal-cancel').onclick=closeModal;$('#setup-apply').onclick=()=>{const settings={size:$('#setup-size').value,orientation:document.querySelector('[name="orientation"]:checked').value,color:$('#setup-color').value};const sides=['top','bottom','left','right'];for(const side of sides){const raw=$('#margin-'+side).value;settings[side]=Number(raw);if(raw===''||!Number.isFinite(settings[side])||settings[side]<0||settings[side]>5){$('#setup-error').textContent='Enter margins between 0 and 5 inches.';return}}const d=PAGE_SIZES[settings.size],width=settings.orientation==='Landscape'?d[1]:d[0],height=settings.orientation==='Landscape'?d[0]:d[1];if(settings.left+settings.right>=width||settings.top+settings.bottom>=height){$('#setup-error').textContent='Margins must leave space for page content.';return}const scope=$('#setup-scope').value;if(scope==='all')working.sections.forEach(s=>s.pageSetup={...settings});else working.sections[+scope].pageSetup={...settings};closeModal();onApply();toast('Page setup applied')};
}
function showTablePicker(onInsert){$('#modal-root').innerHTML=`<div class="overlay"><div class="modal table-picker-modal" role="dialog" aria-modal="true" aria-labelledby="table-picker-title"><div class="modal-head"><h2 id="table-picker-title">Insert table</h2><button class="icon-button" id="modal-close" aria-label="Close">×</button></div><div class="modal-body"><p class="hint">Choose the number of rows and columns.</p><div class="table-grid-picker">${Array.from({length:6},(_,r)=>Array.from({length:8},(_,c)=>`<button data-grid-row="${r+1}" data-grid-col="${c+1}" aria-label="${r+1} rows by ${c+1} columns"></button>`).join('')).join('')}</div><div class="table-picker-size" id="table-picker-size">Select a size</div></div><div class="modal-actions"><button class="button" id="modal-cancel">Cancel</button></div></div></div>`;$('#modal-close').onclick=closeModal;$('#modal-cancel').onclick=closeModal;document.querySelectorAll('[data-grid-row]').forEach(b=>{const highlight=()=>{const r=+b.dataset.gridRow,c=+b.dataset.gridCol;$('#table-picker-size').textContent=`${r} × ${c}`;document.querySelectorAll('[data-grid-row]').forEach(cell=>cell.classList.toggle('marked',+cell.dataset.gridRow<=r&&+cell.dataset.gridCol<=c))};b.onmouseenter=highlight;b.onfocus=highlight;b.onclick=()=>{const r=+b.dataset.gridRow,c=+b.dataset.gridCol;closeModal();onInsert(r,c)}})}
function fieldValues(f){return MASTERS[f.master]||[]}
function sampleInput(f,i){let label=`<label for="sample-${i}">${esc(f.name)}${f.required?' *':''}</label>`, vals=fieldValues(f);if(f.type==='File upload')return `<div class="field sample-field">${label}<input class="input" id="sample-${i}" data-sample="${i}" type="file" accept="${esc(f.allowedTypes.join(','))}" ${+f.maxFiles>1?'multiple':''}><small class="hint">Maximum ${esc(f.maxFiles)} file(s) · ${esc(f.allowedTypes.join(', '))}</small><p class="error" data-upload-error="${i}" role="alert"></p></div>`;if(f.type==='Table')return `<div class="field sample-field"><label>${esc(f.name)}${f.required?' *':''} · sample row</label>${f.columns.map((c,j)=>`<label for="sample-${i}-${j}">${esc(c.name)}</label><input class="input sample-table-cell" id="sample-${i}-${j}" data-sample="${i}" data-column="${j}" placeholder="Sample value">`).join('')}</div>`;if(GRID_TYPES.includes(f.type)){let kind=f.type==='Checkbox grid'?'checkbox':'radio';return `<div class="field sample-field"><label>${esc(f.name)}${f.required?' *':''}</label>${f.rows.filter(x=>x.trim()).map((row,r)=>`<div class="sample-group"><strong>${esc(row)}</strong>${vals.map((v,j)=>`<label class="sample-option"><input type="${kind}" name="grid-${i}-${r}" data-sample="${i}" data-row="${esc(row)}" value="${esc(v)}"> ${esc(v)}</label>`).join('')}</div>`).join('')}</div>`}if(f.type==='Checkboxes'||f.type==='Multiple choice'){let kind=f.type==='Checkboxes'?'checkbox':'radio';return `<div class="field sample-field"><label>${esc(f.name)}${f.required?' *':''}</label>${vals.map((v,j)=>`<label class="sample-option"><input type="${kind}" name="sample-${i}" data-sample="${i}" value="${esc(v)}"> ${esc(v)}</label>`).join('')}</div>`}if(f.type==='Dropdown')return `<div class="field sample-field">${label}<select id="sample-${i}" data-sample="${i}"><option value="">Choose a value</option>${optionList(vals,'')}</select></div>`;if(f.type==='Number')return `<div class="field sample-field">${label}<div class="sample-number"><input class="input" id="sample-${i}" data-sample="${i}" type="number" placeholder="Sample response">${f.suffixValue?`<span>${esc(f.suffixValue)}</span>`:''}</div></div>`;if(f.type==='Paragraph')return `<div class="field sample-field">${label}<textarea class="input" id="sample-${i}" data-sample="${i}" rows="2" placeholder="Sample response"></textarea></div>`;if(['Rating','Linear scale'].includes(f.type))return `<div class="field sample-field">${label}<select id="sample-${i}" data-sample="${i}"><option value="">Choose a value</option>${optionList(Array.from({length:+f.scaleMax},(_,j)=>String(j+1)),'')}</select></div>`;return `<div class="field sample-field">${label}<input class="input" id="sample-${i}" data-sample="${i}" type="${f.type==='Date'?'date':f.type==='Time'?'time':f.type==='Number'?'number':'text'}" placeholder="${f.type==='File upload'?'Example file name':'Sample response'}"></div>`}
function sampleValue(i){const f=working.fields[i],inputs=[...document.querySelectorAll(`[data-sample="${i}"]`)];if(f.type==='File upload'){const files=Array.from(inputs[0]?.files||[]),invalid=files.find(file=>!f.allowedTypes.some(ext=>file.name.toLowerCase().endsWith(ext))),error=document.querySelector(`[data-upload-error="${i}"]`);if(error)error.textContent=files.length>Number(f.maxFiles)?`Choose no more than ${f.maxFiles} files.`:invalid?`File type not allowed: ${invalid.name}`:'';return files.length>Number(f.maxFiles)||invalid?'':files.map(file=>file.name).join(', ')}if(f.type==='Table')return inputs.map((el,j)=>el.value?`${f.columns[j].name}: ${el.value}`:'').filter(Boolean).join('; ');if(GRID_TYPES.includes(f.type)){const rows=f.rows.filter(x=>x.trim());return rows.map(row=>{const checked=inputs.filter(el=>el.dataset.row===row&&el.checked).map(el=>el.value);return checked.length?`${row}: ${checked.join(', ')}`:''}).filter(Boolean).join('; ')}if(['Checkboxes','Multiple choice'].includes(f.type))return inputs.filter(el=>el.checked).map(el=>el.value).join(', ');const value=inputs[0]?.value||'';return f.type==='Number'&&value&&f.suffixValue?`${value} ${f.suffixValue}`:value}
function showPreview(){preview=true;$('#modal-root').innerHTML=`<div class="overlay preview-overlay"><div class="preview-modal" role="dialog" aria-modal="true" aria-labelledby="preview-title"><div class="modal-head"><div><h2 id="preview-title">Document preview</h2><p class="panel-sub">Enter sample responses to see your merged document.</p></div><button class="icon-button" id="modal-close" aria-label="Close preview">×</button></div><div class="preview-content"><aside class="preview-responses"><h3>Sample responses</h3><p class="hint">For preview only</p>${working.fields.map((f,i)=>f.type==='Section'?'':sampleInput(f,i)).join('')||'<p class="hint">No fields defined.</p>'}</aside><div class="preview-paper-wrap"><div class="paper preview-document" id="preview-document"></div></div></div><div class="modal-actions"><button class="button" id="modal-cancel">Close preview</button>${working.status==='Draft'?'<button class="button primary" id="preview-publish">Publish version</button>':''}</div></div></div>`;function update(){working.fields.forEach((f,i)=>{if(f.type==='File upload')sampleValue(i)});const output=$('#preview-document');output.innerHTML=previewSections();output.querySelectorAll('[data-merge-table-id]').forEach(table=>{const i=working.fields.findIndex(f=>f.id===table.dataset.mergeTableId);table.querySelectorAll('.column-resize').forEach(handle=>handle.remove());if(i>=0)table.querySelectorAll('[data-merge-column]').forEach(cell=>{const input=document.querySelector(`[data-sample="${i}"][data-column="${cell.dataset.mergeColumn}"]`);if(input?.value)cell.textContent=input.value})});output.querySelectorAll('[data-field-id]').forEach(el=>{const i=working.fields.findIndex(f=>f.id===el.dataset.fieldId);el.textContent=i<0?'[Field removed]':(sampleValue(i)||`[${working.fields[i].name}]`);el.className='merged-value';el.removeAttribute('contenteditable')})}document.querySelectorAll('[data-sample]').forEach(el=>{el.oninput=update;if(el.type==='file')el.onchange=update});update();$('#modal-close').onclick=closeModal;$('#modal-cancel').onclick=closeModal;if($('#preview-publish'))$('#preview-publish').onclick=()=>{closeModal();publish()};$('.overlay').onclick=e=>{if(e.target===e.currentTarget)closeModal()}}
function closeModal(){$('#modal-root').innerHTML='';preview=false}
function publish(){if(!validateFields())return;$('#modal-root').innerHTML=`<div class="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">Publish version</h2><button class="icon-button" id="modal-close" aria-label="Close">×</button></div><div class="modal-body"><p class="subtitle">Publish <strong>${esc(details.name)} v${working.number}</strong>? This version will become read-only. You can create a new version later.</p></div><div class="modal-actions"><button class="button" id="modal-cancel">Cancel</button><button class="button primary" id="modal-confirm">Publish version</button></div></div></div>`;$('#modal-close').onclick=closeModal;$('#modal-cancel').onclick=closeModal;$('#modal-confirm').onclick=()=>{working.status='Published';working.fieldsSaved=true;syncVersion();closeModal();renderEditor();toast('Version published')}}
